/** Brand icon for a model id, or null when no rule matches. */
@DrawableRes
fun modelBrandIcon(modelId: String): Int? {
    val id = modelId.lowercase()
    return MODEL_ICON_RULES.firstOrNull { (regex, _) -> regex.containsMatchIn(id) }?.second
}
